template <typename T, int N>
struct Container {
    void run() { /* Generic implementation */ }
};

// FULL Specialization (Explicit type T and value N)
template <>
struct Container<bool, 1> {
    void run() { /* Optimized for bool, size 1 */ }
};

// PARTIAL Specialization (Constraining T to a pointer U*)
template <typename U, int N>
struct Container<U*, N> {
    void run() { /* Pointer handling logic */ }
};

// PARTIAL Specialization (Constraining N=0)
template <typename T>
struct Container<T, 0> {
    void run() { /* Empty container handling */ }
};

// Usage examples:
// Container<int, 10> c1; // Uses generic
// Container<bool, 1> c2; // Uses full specialization
// Container<float*, 5> c3; // Uses partial pointer specialization
// Container<char, 0> c4; // Uses partial N=0 specialization
